for i, lang in enumerate(('fr', 'es')):
    p = f'/app/frontend/src/cloudivr/i18n/{lang}.json'
    d = json.load(open(p, encoding='utf-8'))
    before = len(d)
    for k, v in T.items():
        d[k] = v[i]
    was_sorted = list(d)[:-len(T)] == sorted(list(d)[:-len(T)]) if False else True
    with open(p, 'w', encoding='utf-8') as f:
        f.write('{\n' + ',\n'.join(f'{json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)}' for k, v in sorted(d.items())) + '\n}\n')
    print(lang, before, '->', len(d))
